import{_ as l,a8 as a,o as c,c as d,ah as n,K as o}from"./chunks/framework.DwkUJ0oD.js";import"./chunks/theme.DXFaLrA7.js";const g=JSON.parse('{"title":"RAG Query 改写","description":"","frontmatter":{"title":"RAG Query 改写","abstract":"RAG 查询改写技术，讲解历史会话改写、关键词扩写、伪答案改写与缩写词改写等信息不完整类 Query 的优化方法，提升召回精度。","created":"2026-07-08T00:00:00.000Z","tags":["AI","RAG","Query改写"],"type":"概念解释","related":["[[AI 应用核心范式-MOC]]"],"reference":"","category":["🔍 RAG"]},"headers":[],"relativePath":"vault/Knowledge/AI/RAG Query 改写.md","filePath":"vault/Knowledge/AI/RAG Query 改写.md","lastUpdated":1790655645000}'),i={name:"vault/Knowledge/AI/RAG Query 改写.md"};function s(h,e,p,b,u,m){const r=a("NolebaseGitContributors"),t=a("NolebaseGitChangelog");return c(),d("div",null,[e[0]||(e[0]=n('<h1 id="rag-query-改写" tabindex="-1">RAG Query 改写 <a class="header-anchor" href="#rag-query-改写" aria-label="Permalink to “RAG Query 改写”">​</a></h1><p>RAG 流程的第一步通常是对用户 Query 进行改写。用户提问方式与期望答案之间存在差距，改写有助于系统更准确地理解意图，提升召回精度。</p><h2 id="信息不完整类改写" tabindex="-1">信息不完整类改写 <a class="header-anchor" href="#信息不完整类改写" aria-label="Permalink to “信息不完整类改写”">​</a></h2><h3 id="历史会话改写" tabindex="-1">历史会话改写 <a class="header-anchor" href="#历史会话改写" aria-label="Permalink to “历史会话改写”">​</a></h3><p>多轮对话中前后文关联，仅凭当前 Query 会导致召回精度下降。需将上下文信息补全。</p><blockquote><p>用户：「华为 meta70 手机的性能怎么样？」 系统：「……性能表现非常优秀」 用户：「摄像头方面具体改进了什么？」</p><p><strong>改写前</strong>：<code>摄像头方面具体改进了什么？</code><strong>改写后</strong>：<code>华为 meta70 手机的摄像头相比 meta60 有哪些具体改进？</code></p></blockquote><h3 id="关键词扩写" tabindex="-1">关键词扩写 <a class="header-anchor" href="#关键词扩写" aria-label="Permalink to “关键词扩写”">​</a></h3><p>用户输入简短、缺乏上下文时，扩展为完整问句。</p><blockquote><p>输入：<code>机器学习实践</code> 改写后：<code>机器学习在实际应用中的案例有哪些？哪些工具和方法适用于机器学习实践？</code></p></blockquote><h3 id="伪答案改写" tabindex="-1">伪答案改写 <a class="header-anchor" href="#伪答案改写" aria-label="Permalink to “伪答案改写”">​</a></h3><p>在原始查询中加入假设性答案，增强语义丰富性，提升复杂问题检索能力。</p><blockquote><p>输入：<code>如何提高企业的市场竞争力？</code> 改写后：<code>如何提高企业的市场竞争力？比如通过创新产品、优化营销策略或提升客户服务等手段。</code></p></blockquote><h3 id="缩写词改写" tabindex="-1">缩写词改写 <a class="header-anchor" href="#缩写词改写" aria-label="Permalink to “缩写词改写”">​</a></h3><p>将缩写扩展为完整术语，匹配文档中的正式表达。</p><blockquote><p>输入：<code>VR技术在教育中的应用</code> 改写后：<code>虚拟现实（Virtual Reality）技术在教育中的应用有哪些？可以举一些实际的应用案例吗？</code></p></blockquote><h2 id="噪声问题类改写" tabindex="-1">噪声问题类改写 <a class="header-anchor" href="#噪声问题类改写" aria-label="Permalink to “噪声问题类改写”">​</a></h2><h3 id="一般去噪" tabindex="-1">一般去噪 <a class="header-anchor" href="#一般去噪" aria-label="Permalink to “一般去噪”">​</a></h3><p>去除无关修饰语、模糊表达、不相关背景，简化查询。</p><blockquote><p>输入：<code>我最近在准备面试，但对于算法的理解还不太够，能推荐一些有效的学习资源吗？</code> 改写后：<code>有哪些有效的学习资源可以帮助提高算法理解？</code></p></blockquote><h3 id="关键词改写" tabindex="-1">关键词改写 <a class="header-anchor" href="#关键词改写" aria-label="Permalink to “关键词改写”">​</a></h3><p>提取核心关键词，去除停用词和多余描述，适配关键词检索（如 BM25）。</p><blockquote><p>输入：<code>关于Java中的线程池，常见的实现方式有哪些？</code> 改写后：<code>Java线程池常见实现方式</code></p></blockquote><h3 id="子查询拆分" tabindex="-1">子查询拆分 <a class="header-anchor" href="#子查询拆分" aria-label="Permalink to “子查询拆分”">​</a></h3><p>对比类查询可能产生信息干扰，拆分为多个独立查询，分别检索各实体特点。</p><blockquote><p>输入：<code>C++ 和 Go 哪个更适合做系统编程？</code> 拆分后：</p><ul><li><code>C++ 适合做系统编程的优点有哪些？</code></li><li><code>Go 适合做系统编程的优点有哪些？</code></li></ul></blockquote><h2 id="实践建议" tabindex="-1">实践建议 <a class="header-anchor" href="#实践建议" aria-label="Permalink to “实践建议”">​</a></h2><ul><li>改写质量依赖 <strong>Prompt 设计</strong>和<strong>大模型能力</strong></li><li>可进行<strong>多次改写</strong>或<strong>拆分为多个独立查询</strong>提高召回</li><li>结合 <strong>Reranking 重排序模型</strong>对召回结果精确排序</li><li>示例 Prompt： <blockquote><p>您是查询扩展方面的专家。请通过同义词/短语、完整写出缩写、添加额外描述、改变表达方式、翻译等方式扩展用户问题，返回 5 个版本。 <em>（内容由AI生成，仅供参考）</em></p></blockquote></li></ul>',27)),o(r),o(t)])}const A=l(i,[["render",s]]);export{g as __pageData,A as default};
